async function createPost(
  authorId: string,
  data: CreatePostDTO
): Promise<PostWithRelations> {
  const hashtags = data.hashtags?.map((tag) => ({
    hashtag: {
      connectOrCreate: {
        where: { name: tag.toLowerCase() },
        create: { name: tag.toLowerCase() },
      },
    },
  }));

  return prisma.post.create({
    data: {
      authorId,
      content: data.content,
      postType: data.postType ?? 'text',
      visibility: data.visibility ?? 'public',
      parentId: data.parentId,
      repostOfId: data.repostOfId,
      publishedAt: new Date(),
      hashtags: hashtags ? { create: hashtags } : undefined,
      mentions: data.mentionedUserIds
        ? {
            create: data.mentionedUserIds.map((userId) => ({
              mentionedUserId: userId,
            })),
          }
        : undefined,
    },
    include: {
      author: true,
      media: true,
      hashtags: { include: { hashtag: true } },
    },
  }) as Promise<PostWithRelations>;
}
